import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { createDecipheriv, createCipheriv, randomBytes } from 'crypto';

const ALGORITHM = 'aes-256-cbc';
const KEY = Buffer.from(process.env.ENCRYPTION_KEY || 'a'.repeat(64), 'hex');

interface DecryptRequest {
  ciphertext: string;
  iv: string;
}

interface EncryptRequest {
  plaintext: string;
}

@Controller('api/v2/tokens')
export class TokenController {

  @Post('encrypt')
  encrypt(@Body() body: EncryptRequest): { ciphertext: string; iv: string } {
    const iv = randomBytes(16);
    const cipher = createCipheriv(ALGORITHM, KEY, iv);
    let encrypted = cipher.update(body.plaintext, 'utf8', 'base64');
    encrypted += cipher.final('base64');
    return { ciphertext: encrypted, iv: iv.toString('base64') };
  }

  @Post('decrypt')
  decrypt(@Body() body: DecryptRequest): { status: string; data?: string } {
    try {
      const iv = Buffer.from(body.iv, 'base64');
      const ciphertext = Buffer.from(body.ciphertext, 'base64');

      if (iv.length !== 16) {
        throw new HttpException('Invalid IV length', HttpStatus.BAD_REQUEST);
      }

      const decipher = createDecipheriv(ALGORITHM, KEY, iv);
      let decrypted = decipher.update(ciphertext);
      decrypted = Buffer.concat([decrypted, decipher.final()]);

      return { status: 'ok', data: decrypted.toString('utf8') };
    } catch (error) {
      if (error instanceof HttpException) {
        throw error;
      }
      // Padding error vs other errors leak different responses
      if (error.message && error.message.includes('bad decrypt')) {
        throw new HttpException(
          { status: 'error', code: 'PADDING_ERROR', message: 'Decryption failed: invalid padding' },
          HttpStatus.BAD_REQUEST
        );
      }
      if (error.message && error.message.includes('wrong final block')) {
        throw new HttpException(
          { status: 'error', code: 'BLOCK_ERROR', message: 'Decryption failed: block length' },
          HttpStatus.UNPROCESSABLE_ENTITY
        );
      }
      throw new HttpException(
        { status: 'error', code: 'INTERNAL_ERROR', message: 'Unexpected failure' },
        HttpStatus.INTERNAL_SERVER_ERROR
      );
    }
  }

  @Post('validate')
  validate(@Body() body: DecryptRequest): { valid: boolean } {
    try {
      const iv = Buffer.from(body.iv, 'base64');
      const ciphertext = Buffer.from(body.ciphertext, 'base64');
      const decipher = createDecipheriv(ALGORITHM, KEY, iv);
      decipher.update(ciphertext);
      decipher.final();
      return { valid: true };
    } catch {
      return { valid: false };
    }
  }

  @Post('refresh')
  refresh(@Body() body: { token: string }): { refreshed: string } {
    // Re-encrypts token data after validation
    const parts = body.token.split('.');
    if (parts.length !== 2) {
      throw new HttpException('Malformed token', HttpStatus.BAD_REQUEST);
    }
    const [ivB64, ciphertextB64] = parts;
    const iv = Buffer.from(ivB64, 'base64');
    const ciphertext = Buffer.from(ciphertextB64, 'base64');
    const decipher = createDecipheriv(ALGORITHM, KEY, iv);
    let plain = decipher.update(ciphertext);
    plain = Buffer.concat([plain, decipher.final()]);
    // Re-encrypt with fresh IV
    const newIv = randomBytes(16);
    const cipher = createCipheriv(ALGORITHM, KEY, newIv);
    let reEncrypted = cipher.update(plain);
    reEncrypted = Buffer.concat([reEncrypted, cipher.final()]);
    return { refreshed: `${newIv.toString('base64')}.${reEncrypted.toString('base64')}` };
  }
}
